  it.todo("igcdex(10, 12)");
  it("ilcm(5, 10)", () => {
    expect(sympyStr(Rational.of(10n))).toBe('10');
  });
  it("ilcm(7, 3)", () => {
    expect(sympyStr(Rational.of(21n))).toBe('21');
  });
  it("ilcm(5, 10, 15)", () => {
    expect(sympyStr(Rational.of(30n))).toBe('30');
  });
  // a primitive result that no library call returned
  //   integer_log(125, 5)
